// Relays NinjaOne and Datto RMM alerts to TriageOps and signs each one.
// The RMM proves itself to this workflow with a static header that the Webhook node checks.
// TriageOps only accepts its own timestamped HMAC, so this node signs for it.
// Signature = "sha256=" + hex HMAC-SHA256 of "{timestamp}.{rawBody}" with the TriageOps secret.
// The HTTP Request node sends rawBody byte for byte, so the server computes the same HMAC.
// n8n settings needed: NODE_FUNCTION_ALLOW_BUILTIN=crypto and N8N_BLOCK_ENV_ACCESS_IN_NODE=false.
const crypto = require('crypto');

// Same order as the server: the RMM secret first, then the shared webhook secret.
const secret = $env.TRIAGEOPS_RMM_WEBHOOK_SECRET || $env.TRIAGEOPS_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('TRIAGEOPS_RMM_WEBHOOK_SECRET or TRIAGEOPS_WEBHOOK_SECRET must be set in the n8n environment');
}

// Datto leaves a variable it cannot fill as the literal name, for example "[alert_priority]".
const PLACEHOLDER = /^\[[A-Za-z0-9_\-]+\]$/;
const RAW_TEXT_LIMIT = 8000;
const LABEL_LIMIT = 120;

// Body keys that tell a raised Datto alert from a resolved one, and the keys that carry its priority.
const EVENT_KEYS = ['event', 'status', 'alertlevel', 'alert_resolved', 'alertresolved', 'resolved'];
const PRIORITY_KEYS = ['priority', 'alert_priority', 'severity'];
const EVENT_VALUES = { triggered: 'triggered', raised: 'raised', resolved: 'resolved' };
const PRIORITY_VALUES = {
  critical: 'Critical', high: 'High', moderate: 'Moderate', low: 'Low', information: 'Information',
};

// Simple string fields worth rescuing from a Datto template that is not valid JSON.
const SALVAGE_KEYS = [
  'source', 'event', 'status', 'alertlevel', 'alert_uid', 'alertuid', 'priority', 'alert_priority',
  'severity', 'alert_type', 'alert_category', 'alert', 'device_uid', 'device_id', 'device_hostname',
  'hostname', 'device_description', 'device_os', 'site_uid', 'site_id', 'site_name', 'sitename',
  'platform', 'timestamp',
];

// Vendor detection, the same rules as triageops/rmm/parsers.py detect_vendor.
const SOURCE_ALIASES = { ninjaone: 'ninjaone', ninja: 'ninjaone', datto: 'datto', dattormm: 'datto' };
// Keys only a NinjaOne activity carries, in exact case.
const NINJA_KEYS = ['activityType', 'statusCode', 'sourceConfigUid', 'seriesUid', 'activityTime'];
// Keys a Datto RMM template or API alert carries, compared in lower case.
const DATTO_KEYS = [
  'alert_uid', 'alertuid', 'device_uid', 'deviceuid', 'device_hostname', 'alert_type', 'alert_category',
  'alert_message', 'alertmessage', 'alertsourceinfo', 'alertcontext', 'site_name', 'sitename', 'alerts',
];

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function usable(value) {
  if (typeof value === 'boolean' || typeof value === 'number') return true;
  if (typeof value !== 'string') return false;
  const text = value.trim();
  return text !== '' && !PLACEHOLDER.test(text);
}

function lowerKeys(body) {
  return Object.keys(body).map((key) => key.toLowerCase());
}

// An explicit ?source= wins. An unknown value becomes "unknown" so TriageOps rejects it
// and the fallback message says why. An empty result lets TriageOps detect the shape itself.
function detectVendor(body, querySource) {
  const explicit = String(querySource || '').trim().toLowerCase();
  if (explicit) return SOURCE_ALIASES[explicit] || 'unknown';
  if (NINJA_KEYS.some((key) => key in body)) return 'ninjaone';
  const keys = lowerKeys(body);
  if (DATTO_KEYS.some((key) => keys.includes(key))) return 'datto';
  return '';
}

// Keeps the well formed "key":"value" pairs of a broken template so the alert can still be matched.
function salvage(text) {
  const found = {};
  const pair = /"([A-Za-z_][A-Za-z0-9_]*)"\s*:\s*"((?:[^"\\]|\\.)*)"(?=\s*[,}])/g;
  let match;
  while ((match = pair.exec(text)) !== null) {
    const key = match[1];
    if (!SALVAGE_KEYS.includes(key.toLowerCase()) || key in found) continue;
    let value = match[2];
    try {
      value = JSON.parse(`"${value}"`);
    } catch (error) {
      // Keep the text as it arrived when it holds an escape JSON does not allow.
    }
    found[key] = value;
  }
  found.alert_message = text.slice(0, RAW_TEXT_LIMIT);
  return found;
}

// The Webhook node gives an object for JSON and form bodies and a string for text/plain.
function toObject(body) {
  if (isObject(body)) return body;
  const text = (typeof body === 'string' ? body : JSON.stringify(body) || '').replace(/^\uFEFF/, '').trim();
  try {
    const parsed = JSON.parse(text);
    if (isObject(parsed)) return parsed;
  } catch (error) {
    // Datto does not JSON escape the values it fills in, so fall through and rescue the text.
  }
  return salvage(text || '(the RMM sent an empty body)');
}

function hasUsable(body, keys) {
  return Object.keys(body).some((key) => keys.includes(key.toLowerCase()) && usable(body[key]));
}

function setKey(body, name, value) {
  const existing = Object.keys(body).find((key) => key.toLowerCase() === name);
  body[existing || name] = value;
}

// Global Webhooks can send resolved alerts to a separate URL, so ?event= and ?priority= fill gaps.
function mergeQuery(alert, query) {
  const merged = { ...alert };
  const event = EVENT_VALUES[String(query.event || '').trim().toLowerCase()];
  if (event && !hasUsable(merged, EVENT_KEYS)) setKey(merged, 'event', event);
  const priority = PRIORITY_VALUES[String(query.priority || '').trim().toLowerCase()];
  if (priority && !hasUsable(merged, PRIORITY_KEYS)) setKey(merged, 'priority', priority);
  return merged;
}

// A Datto API alerts page holds a list. TriageOps takes one alert per request.
function dattoAlerts(body) {
  if (!Array.isArray(body.alerts)) return [body];
  const alerts = body.alerts.filter(isObject);
  if (alerts.length) return alerts;
  return body.alerts.length ? [body] : [];
}

function clean(value) {
  return usable(value) ? String(value).replace(/\s+/g, ' ').trim().slice(0, LABEL_LIMIT) : '';
}

function pick(body, names) {
  for (const name of names) {
    const key = Object.keys(body).find((candidate) => candidate.toLowerCase() === name);
    if (key && clean(body[key])) return clean(body[key]);
  }
  return '';
}

// A short label for the fallback message. It never carries the alert text itself.
function describe(body, source) {
  if (source === 'ninjaone') {
    const device = isObject(body.device) ? body.device : {};
    return {
      device: clean(device.displayName) || clean(device.systemName) || clean(device.dnsName)
        || (clean(body.deviceId) ? `device ${clean(body.deviceId)}` : ''),
      condition: clean(body.sourceName) || clean(body.subject),
    };
  }
  const info = isObject(body.alertSourceInfo) ? body.alertSourceInfo : {};
  return {
    device: pick(body, ['device_hostname', 'hostname']) || clean(info.deviceName),
    condition: pick(body, ['alert_type', 'alert_category'])
      || (isObject(body.alertContext) ? clean(body.alertContext['@class']) : ''),
  };
}

function sign(rawBody) {
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = 'sha256=' + crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.${rawBody}`, 'utf8')
    .digest('hex');
  return { timestamp, signature };
}

const output = [];
for (const item of $input.all()) {
  const query = isObject(item.json.query) ? item.json.query : {};
  const body = toObject(item.json.body);
  const source = detectVendor(body, query.source);
  const alerts = source === 'datto' ? dattoAlerts(body).map((alert) => mergeQuery(alert, query)) : [body];
  for (const alert of alerts) {
    const rawBody = JSON.stringify(alert);
    output.push({ json: { rawBody, ...sign(rawBody), source, ...describe(alert, source) } });
  }
}
return output;

// Builds a short plain message for a chat channel when an RMM alert cannot reach TriageOps.
// The body suits the host of TRIAGEOPS_FALLBACK_WEBHOOK_URL: Teams Workflows, Slack, Discord or generic.
// The message names the vendor, device and condition only. It never carries the alert text.
const url = String($env.TRIAGEOPS_FALLBACK_WEBHOOK_URL || '').trim();
if (!/^https:\/\/[^\s/]+/i.test(url)) {
  throw new Error('TRIAGEOPS_FALLBACK_WEBHOOK_URL must be set to an https URL in the n8n environment');
}
const host = url.replace(/^https:\/\//i, '').split(/[/:?#]/)[0].toLowerCase();

const VENDORS = { ninjaone: 'NinjaOne', datto: 'Datto RMM' };

function clean(value, limit) {
  return String(value || '').replace(/\s+/g, ' ').trim().slice(0, limit);
}

function reasonOf(error) {
  if (!error) return 'n8n gave no detail';
  const text = typeof error === 'string' ? error : error.message || error.description || 'n8n gave no detail';
  return clean(text, 300).replace(/[.\s]+$/, '');
}

function messageFor(json) {
  const vendor = VENDORS[json.source] || 'An unknown RMM';
  const about = [json.device ? `device ${clean(json.device, 120)}` : '', clean(json.condition, 120)]
    .filter(Boolean).join(', ');
  const stage = json.signature ? 'could not be delivered to TriageOps after three attempts'
    : 'could not be signed or sent to TriageOps';
  return [
    `${vendor} alert ${stage}${about ? ` (${about})` : ''}.`,
    `Reason: ${reasonOf(json.error)}.`,
    `Open n8n execution ${$execution.id} to see the alert and send it again.`,
  ].join('\n');
}

function escapeCard(text) {
  return text.replace(/([\\`*_\[\]<>#|{}&~])/g, '\\$1');
}

function escapeSlack(text) {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function payloadFor(text) {
  const teams = ['.webhook.office.com', '.logic.azure.com', '.powerplatform.com'];
  if (teams.some((suffix) => host.endsWith(suffix))) {
    return {
      type: 'message',
      attachments: [{
        contentType: 'application/vnd.microsoft.card.adaptive',
        contentUrl: null,
        content: {
          $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
          type: 'AdaptiveCard',
          version: '1.4',
          msteams: { width: 'Full' },
          body: [
            { type: 'TextBlock', text: 'RMM alert not delivered', weight: 'Bolder', color: 'Attention', wrap: true },
            { type: 'TextBlock', text: escapeCard(text), wrap: true },
          ],
        },
      }],
    };
  }
  if (host === 'hooks.slack.com') return { text: escapeSlack(text) };
  if (host === 'discord.com' || host === 'discordapp.com') return { content: text.slice(0, 1900) };
  return { text, content: text };
}

return $input.all().map((item) => ({
  json: { fallbackBody: JSON.stringify(payloadFor(messageFor(item.json))) },
}));
